// Decides which invoices get a "coming up" or "due today" reminder.
// remind_days_before = "3,0" means: once when 3 or fewer days remain, and again
// on the due date. Sent offsets are logged in the pre_due_reminders column, so a
// missed day (server down, weekend) is caught up without double-sending.
// Overdue invoices are left to the "Invoice follow-ups" workflow.
// ---- dates (shared helper, inlined at build time) ----
// Sheet dates arrive as serial numbers (date cells read as SERIAL_NUMBER), ISO
// text ("2026-10-31"), or day/month text whose order depends on DATE_FORMAT.
function isoFromParts(y, m, d) {
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return dt.toISOString().slice(0, 10);
}

function toIsoDate(value, dateFormat) {
  if (value === null || value === undefined) return null;
  const s = String(value).trim();
  if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) {
    const serial = Number(s);
    if (serial < 20000 || serial > 80000) return null; // not a plausible 1954-2119 date
    return new Date(Date.UTC(1899, 11, 30) + Math.floor(serial) * 86400000).toISOString().slice(0, 10);
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ].*)?$/);
  if (m) return isoFromParts(+m[1], +m[2], +m[3]);
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  if (m) {
    const [a, b, y] = [+m[1], +m[2], +m[3]];
    return String(dateFormat).toUpperCase().startsWith('MM') ? isoFromParts(y, a, b) : isoFromParts(y, b, a);
  }
  const parsed = new Date(s); // "Oct 31, 2026", "31 October 2026"
  if (!isNaN(parsed)) return isoFromParts(parsed.getFullYear(), parsed.getMonth() + 1, parsed.getDate());
  return null;
}

/** Whole days from `fromIso` to `toIso` (positive when toIso is later). */
function daysBetween(fromIso, toIso) {
  const [a, b] = [fromIso, toIso].map((iso) => {
    const [y, m, d] = iso.split('-').map(Number);
    return Date.UTC(y, m - 1, d);
  });
  return Math.round((b - a) / 86400000);
}

function displayDate(iso, locale) {
  const [y, m, d] = iso.split('-').map(Number);
  try {
    return new Intl.DateTimeFormat(locale || 'en-US', { dateStyle: 'medium', timeZone: 'UTC' }).format(new Date(Date.UTC(y, m - 1, d)));
  } catch {
    return iso;
  }
}
// ---- text + email layout (shared helper, inlined at build time) ----
function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

/** Replace {placeholders}; unknown placeholders are left visible so typos get noticed. */
function fill(template, vars) {
  return String(template ?? '').replace(/\{(\w+)\}/g, (match, key) => (key in vars ? String(vars[key] ?? '') : match));
}

function isEmail(s) {
  return /^[^\s@<>(),;:]+@[^\s@<>(),;:]+\.[a-z]{2,}$/i.test(String(s ?? '').trim());
}

function firstName(fullName) {
  const first = String(fullName ?? '').trim().split(/\s+/)[0] || '';
  return first ? first.charAt(0).toUpperCase() + first.slice(1) : '';
}

/** "1,250.00", "$1250", 1250 -> 1250. Returns null when no number is present. */
function toAmount(value) {
  if (typeof value === 'number') return value;
  const cleaned = String(value ?? '').replace(/[^0-9.-]/g, '');
  if (!cleaned || isNaN(Number(cleaned))) return null;
  return Number(cleaned);
}

function money(amount, currency, locale) {
  if (amount === null || amount === undefined) return '';
  try {
    return new Intl.NumberFormat(locale || 'en-US', { style: 'currency', currency: (currency || 'USD').toUpperCase() }).format(amount);
  } catch {
    return `${currency || ''} ${Number(amount).toFixed(2)}`.trim();
  }
}

/** Plain text with blank-line paragraphs -> simple HTML paragraphs. */
function textToHtml(text) {
  return String(text ?? '')
    .trim()
    .split(/\n\s*\n/)
    .map((p) => `<p style="margin:0 0 14px">${escapeHtml(p.trim()).replace(/\n/g, '<br>')}</p>`)
    .join('\n');
}

/** Minimal, client-safe HTML email: paragraphs, optional button, small footer. */
function emailHtml({ bodyText, buttonLabel, buttonUrl, footer }) {
  const button = buttonUrl
    ? `<p style="margin:22px 0"><a href="${escapeHtml(buttonUrl)}" style="background:#1f6feb;color:#ffffff;text-decoration:none;padding:11px 20px;border-radius:6px;display:inline-block;font-weight:600">${escapeHtml(buttonLabel || 'Open link')}</a></p>`
    : '';
  const foot = footer ? `<p style="margin:24px 0 0;color:#6b7280;font-size:12px">${escapeHtml(footer)}</p>` : '';
  return `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#111827;max-width:560px">\n${textToHtml(bodyText)}\n${button}${foot}\n</div>`;
}

/** Owner-facing HTML table. rows: array of arrays of cell text. */
function htmlTable(headers, rows) {
  const th = headers.map((h) => `<th style="text-align:left;padding:6px 10px;border-bottom:1px solid #d1d5db;font-size:13px">${escapeHtml(h)}</th>`).join('');
  const body = rows
    .map((r) => `<tr>${r.map((c) => `<td style="padding:6px 10px;border-bottom:1px solid #eef0f3;font-size:13px">${escapeHtml(c)}</td>`).join('')}</tr>`)
    .join('\n');
  return `<table style="border-collapse:collapse;margin:8px 0 18px">\n<tr>${th}</tr>\n${body}\n</table>`;
}
// ---- invoice rows (shared helper, inlined at build time) ----
// One "Invoices" sheet drives both pre-due reminders and post-due follow-ups.
// Only rows whose status is explicitly open are ever contacted; a blank status
// is treated as "not ready" so a forgotten Paid mark never triggers a dunning email.
const OPEN_STATUSES = ['unpaid', 'open', 'sent', 'due', 'overdue', 'partial', 'partially paid'];
const CLOSED_STATUSES = ['paid', 'void', 'cancelled', 'canceled', 'disputed', 'paused', 'written off', 'refunded', 'draft'];

/** Normalise one sheet row. Returns { ok, reason, invoice }. */
function readInvoiceRow(row, cfg) {
  const status = String(row.status ?? '').trim().toLowerCase();
  const id = String(row.invoice_id ?? '').trim();
  if (!id) return { ok: false, reason: 'missing invoice_id', closed: false };
  if (CLOSED_STATUSES.includes(status)) return { ok: false, reason: `status ${status}`, closed: true };
  if (!OPEN_STATUSES.includes(status)) return { ok: false, reason: status ? `unknown status "${row.status}"` : 'blank status', closed: false };
  const email = String(row.client_email ?? '').trim();
  if (!isEmail(email)) return { ok: false, reason: email ? `bad email "${email}"` : 'missing client_email', closed: false };
  const due = toIsoDate(row.due_date, cfg.date_format);
  if (!due) return { ok: false, reason: `unreadable due_date "${row.due_date ?? ''}"`, closed: false };
  const amount = toAmount(row.amount);
  if (amount === null) return { ok: false, reason: `unreadable amount "${row.amount ?? ''}"`, closed: false };
  const currency = String(row.currency || cfg.default_currency || 'USD').trim().toUpperCase();
  return {
    ok: true,
    invoice: {
      invoice_id: id,
      client_name: String(row.client_name ?? '').trim(),
      client_email: email,
      client_phone: String(row.client_phone ?? '').trim(),
      amount,
      currency,
      due_date: due,
      payment_link: String(row.payment_link ?? '').trim(),
      reminder_stage: Math.max(0, Math.min(3, parseInt(row.reminder_stage, 10) || 0)),
      last_reminder_at: toIsoDate(row.last_reminder_at, 'YYYY-MM-DD'),
      pre_due_reminders: String(row.pre_due_reminders ?? '').trim(),
    },
  };
}

/** Placeholder values every template can use. */
function invoiceVars(inv, cfg, today) {
  const daysOverdue = daysBetween(inv.due_date, today);
  return {
    client_name: inv.client_name || 'there',
    first_name: firstName(inv.client_name) || 'there',
    invoice_id: inv.invoice_id,
    amount: money(inv.amount, inv.currency, cfg.locale),
    due_date: displayDate(inv.due_date, cfg.locale),
    days_overdue: Math.max(0, daysOverdue),
    days_until_due: Math.max(0, -daysOverdue),
    business_name: cfg.business_name,
    sender_name: cfg.sender_name,
    payment_link: inv.payment_link,
    payment_instructions: cfg.payment_instructions || '',
  };
}
const cfg = $('Config').first().json;
const today = $now.toISODate();
const testMode = cfg.test_mode === true || String(cfg.test_mode).toLowerCase() === 'true';
const smsEnabled = cfg.sms_enabled === true || String(cfg.sms_enabled).toLowerCase() === 'true';
const offsets = [...new Set(String(cfg.remind_days_before || '3,0').split(',').map((s) => parseInt(s, 10)).filter((n) => n >= 0))].sort((a, b) => b - a);
const isPhone = (p) => /^\+[1-9]\d{7,14}$/.test(String(p).replace(/[\s().-]/g, ''));

const out = [];
$input.all().forEach((item, index) => {
  const parsed = readInvoiceRow(item.json, cfg);
  if (!parsed.ok) return;
  const inv = parsed.invoice;
  const daysUntil = daysBetween(today, inv.due_date);
  if (daysUntil < 0 || inv.reminder_stage > 0) return;

  const done = new Set(inv.pre_due_reminders.split(/[,\s]+/).filter(Boolean).map(Number));
  const reached = offsets.filter((k) => daysUntil <= k);
  if (!reached.some((k) => !done.has(k))) return;

  const vars = invoiceVars(inv, cfg, today);
  vars.due_phrase = daysUntil === 0 ? 'today' : daysUntil === 1 ? 'tomorrow' : `in ${daysUntil} days`;
  const dueToday = daysUntil === 0;
  const subject = fill(dueToday ? cfg.due_today_subject : cfg.upcoming_subject, vars);
  const phone = inv.client_phone.replace(/[\s().-]/g, '');
  const smsTo = !smsEnabled ? '' : testMode ? (isPhone(cfg.owner_phone) ? String(cfg.owner_phone).replace(/[\s().-]/g, '') : '') : isPhone(phone) ? phone : '';

  out.push({
    json: {
      invoice_id: inv.invoice_id,
      client_name: inv.client_name,
      client_email: inv.client_email,
      amount_display: vars.amount,
      days_until_due: daysUntil,
      to: testMode ? cfg.owner_email : inv.client_email,
      subject: testMode ? `[TEST -> ${inv.client_email}] ${subject}` : subject,
      html: emailHtml({
        bodyText: fill(dueToday ? cfg.due_today_body : cfg.upcoming_body, vars),
        buttonLabel: `Pay ${vars.amount}`,
        buttonUrl: inv.payment_link,
        footer: `${cfg.business_name} · Invoice ${inv.invoice_id}`,
      }),
      sms_to: smsTo,
      sms_text: fill(cfg.sms_template, vars).replace(/\s+/g, ' ').trim().slice(0, 320),
      pre_due_reminders: [...new Set([...done, ...reached])].sort((a, b) => b - a).join(','),
      test_mode: testMode,
    },
    pairedItem: { item: index },
  });
});

return out;

